    public boolean IsCompleted() {
        return _isCompleted;
    }

    @Override
    public void SetCompleted() {
        _isCompleted = true;
    }

    @Override
    public int GetSpriteID() {
        if (_sprite.isID)
            return _sprite.idValue;
        else return APTask.IconByName(_sprite.nameValue);
    }

