package gg.archipelago.data;

import java.util.regex.Pattern;

/**
 * Class for containing data parsed from the CSV document that can be either an ID or a name, for legacy
 * compatibility purposes.
 *
 * Create it with the raw string from the CSV. If it's a number, it'll populate that value.
 */
public class NameOrIDDataSource {
    public boolean isID;
    public int idValue;
    public String nameValue;
    public NameOrIDDataSource(String data){
        if (isNumeric(data)){
            isID = true;
            idValue = Integer.parseInt(data);
        } else {
            isID = false;
            nameValue = data;
        }
    }
    public NameOrIDDataSource(int data){
        isID = true;
        idValue = data;
    }

    private final Pattern integerPattern = Pattern.compile("^[+-]?[1-9][0-9]*|0$ or ^[+-]?[1-9]\\d*|0$");

    public boolean isNumeric(String strNum) {
        if (strNum == null) {
            return false;
        }
        return integerPattern.matcher(strNum).matches();
    }
}

package gg.archipelago.ui;

import net.runelite.client.ui.ColorScheme;

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.table.*;

/**
 * Source: https://github.com/tips4java/tips4java/blob/main/source/ButtonColumn.java
 */

/**
 *  The ButtonColumn class provides a renderer and an editor that looks like a
 *  JButton. The renderer and editor will then be used for a specified column
 *  in the table. The TableModel will contain the String to be displayed on
 *  the button.
 *
 *  The button can be invoked by a mouse click or by pressing the space bar
 *  when the cell has focus. Optionaly a mnemonic can be set to invoke the
 *  button. When the button is invoked the provided Action is invoked. The
 *  source of the Action will be the table. The action command will contain
 *  the model row number of the button that was clicked.
 *
 */
public class ButtonColumn extends AbstractCellEditor
        implements TableCellRenderer, TableCellEditor, ActionListener, MouseListener
{
    private JTable table;
    private Action action;
    private int mnemonic;
    private Border originalBorder;
    private Border focusBorder;

    private JButton renderButton;
    private JButton editButton;
    private Object editorValue;
    private boolean isButtonColumnEditor;

    /**
     *  Create the ButtonColumn to be used as a renderer and editor. The
     *  renderer and editor will automatically be installed on the TableColumn
     *  of the specified column.
     *
     *  @param table the table containing the button renderer/editor
     *  @param action the Action to be invoked when the button is invoked
     *  @param column the column to which the button renderer/editor is added
     */
    public ButtonColumn(JTable table, Action action, int column)
    {
        this.table = table;
        this.action = action;

        renderButton = new JButton();
        editButton = new JButton();
        editButton.setFocusPainted( false );
        editButton.addActionListener( this );
        originalBorder = editButton.getBorder();
        setFocusBorder( new LineBorder(ColorScheme.BRAND_ORANGE) );

        TableColumnModel columnModel = table.getColumnModel();
        columnModel.getColumn(column).setCellRenderer( this );
        columnModel.getColumn(column).setCellEditor( this );
        table.addMouseListener( this );
    }


    /**
     *  Get foreground color of the button when the cell has focus
     *
     *  @return the foreground color
     */
    public Border getFocusBorder()
    {
        return focusBorder;
    }

    /**
     *  The foreground color of the button when the cell has focus
     *
     *  @param focusBorder the foreground color
     */
    public void setFocusBorder(Border focusBorder)
    {
        this.focusBorder = focusBorder;
        editButton.setBorder( focusBorder );
    }

    public int getMnemonic()
    {
        return mnemonic;
    }

    /**
     *  The mnemonic to activate the button when the cell has focus
     *
     *  @param mnemonic the mnemonic
     */
    public void setMnemonic(int mnemonic)
    {
        this.mnemonic = mnemonic;
        renderButton.setMnemonic(mnemonic);
        editButton.setMnemonic(mnemonic);
/*
		Action mnemonicAction = new AbstractAction()
		{
			public void actionPerformed(ActionEvent e)
			{
				ButtonColumn.this.actionPerformed(e);
			}
		};

		String key = "mnemonicAction";
		KeyStroke keyStroke = KeyStroke.getKeyStroke(mnemonic, 0);
		editButton.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(keyStroke, key);
		editButton.getActionMap().put(key, mnemonicAction);
*/
    }

    @Override
    public Component getTableCellEditorComponent(
            JTable table, Object value, boolean isSelected, int row, int column)
    {
        if (value == null)
        {
            editButton.setText( "" );
            editButton.setIcon( null );
        }
        else if (value instanceof Icon)
        {
            editButton.setText( "" );
            editButton.setIcon( (Icon)value );
        }
        else
        {
            editButton.setText( value.toString() );
            editButton.setIcon( null );
        }

        this.editorValue = value;
        return editButton;
    }

    @Override
    public Object getCellEditorValue()
    {
        return editorValue;
    }

    //
//  Implement TableCellRenderer interface
//
    public Component getTableCellRendererComponent(
            JTable table, Object value, boolean isSelected, boolean hasFocus, int row, int column)
    {
        if (isSelected)
        {
            renderButton.setForeground(table.getSelectionForeground());
            renderButton.setBackground(table.getSelectionBackground());
        }
        else
        {
            renderButton.setForeground(table.getForeground());
            renderButton.setBackground(UIManager.getColor("Button.background"));
        }

        if (hasFocus)
        {
            renderButton.setBorder( focusBorder );
        }
        else
        {
            renderButton.setBorder( originalBorder );
        }

//		renderButton.setText( (value == null) ? "" : value.toString() );
        if (value == null)
        {
            renderButton.setText( "" );
            renderButton.setIcon( null );
        }
        else if (value instanceof Icon)
        {
            renderButton.setText( "" );
            renderButton.setIcon( (Icon)value );
        }
        else
        {
            renderButton.setText( value.toString() );
            renderButton.setIcon( null );
        }

        return renderButton;
    }

    //
//  Implement ActionListener interface
//
    /*
     *	The button has been pressed. Stop editing and invoke the custom Action
     */
    public void actionPerformed(ActionEvent e)
    {
        int row = table.convertRowIndexToModel( table.getEditingRow() );
        fireEditingStopped();

        //  Invoke the Action

        ActionEvent event = new ActionEvent(
                table,
                ActionEvent.ACTION_PERFORMED,
                "" + row);
        action.actionPerformed(event);
    }

    //
//  Implement MouseListener interface
//
    /*
     *  When the mouse is pressed the editor is invoked. If you then then drag
     *  the mouse to another cell before releasing it, the editor is still
     *  active. Make sure editing is stopped when the mouse is released.
     */
    public void mousePressed(MouseEvent e)
    {
        if (table.isEditing()
                &&  table.getCellEditor() == this)
            isButtonColumnEditor = true;
    }

    public void mouseReleased(MouseEvent e)
    {
        if (isButtonColumnEditor
                &&  table.isEditing())
            table.getCellEditor().stopCellEditing();

        isButtonColumnEditor = false;
    }

    public void mouseClicked(MouseEvent e) {}
    public void mouseEntered(MouseEvent e) {}
    public void mouseExited(MouseEvent e) {}
}

package gg.archipelago.ui;

import gg.archipelago.ArchipelagoPlugin;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import java.awt.*;

@Slf4j
public class GoalPanel extends JPanel{
    private JButton taskName;
    private final ArchipelagoPlugin plugin;

    public String goal;

    public GoalPanel(String goal, ArchipelagoPlugin plugin){
        this.plugin = plugin;

        setLayout(new BorderLayout());
        setPreferredSize(new Dimension(0, 50));
        setAlignmentX(Component.LEFT_ALIGNMENT);

        taskName = new JButton(WrapTaskNameText(goal));
        Font f = taskName.getFont();
        taskName.setFont(new Font(f.getName(), f.getStyle(), 32));
        taskName.setHorizontalAlignment(SwingConstants.CENTER);
        taskName.addActionListener(e -> ManuallyComplete());

        add(taskName, BorderLayout.CENTER);

        taskName.setPreferredSize(taskName.getPreferredSize());
        if (taskName.getPreferredSize().height > getPreferredSize().height){
            setMinimumSize(taskName.getPreferredSize());
            setMaximumSize(taskName.getPreferredSize());
        }
    }

    public void ManuallyComplete(){
        JFrame frame = (JFrame) SwingUtilities.getWindowAncestor(this);
        int result = JOptionPane.showConfirmDialog(
                frame,
                "Complete your Goal?", "Goal Complete",
                JOptionPane.OK_CANCEL_OPTION,
                JOptionPane.QUESTION_MESSAGE);
        if (result == JOptionPane.OK_OPTION){
            log.info("Completed task "+goal);
            plugin.goalCompleted = true;
        }
    }

    private String WrapTaskNameText(String taskName){
        StringBuilder sb = new StringBuilder("<html><div style='text-align:center;padding:2px'>");
        sb.append("Your goal is: <br />");
        taskName = taskName.replace("~|","<font color='#ffff00'>").replace("|~","</font>");
        sb.append(taskName);
        sb.append("</div></html>");
        return sb.toString();
    }
}

